class Solution {
public:
    int minimumCost(vector<int>& start, vector<int>& target, vector<vector<int>>& specialRoads) {
        vector<pair<int,int>> points;
        points.push_back({start[0], start[1]});
        points.push_back({target[0], target[1]});

        for (auto& r : specialRoads) {
            points.push_back({r[0], r[1]});
            points.push_back({r[2], r[3]});
        }

        sort(points.begin(), points.end());
        points.erase(unique(points.begin(), points.end()), points.end());

        int n = points.size();

        map<pair<int,int>, int> idx;
        for (int i = 0; i < n; i++) {
            idx[points[i]] = i;
        }

        int src = idx[{start[0], start[1]}];
        int dst = idx[{target[0], target[1]}];

        vector<vector<pair<int,int>>> specialAdj(n);
        for (auto& r : specialRoads) {
            int u = idx[{r[0], r[1]}];
            int v = idx[{r[2], r[3]}];
            specialAdj[u].push_back({v, r[4]});
        }

        const long long INF = 1e18;
        vector<long long> dist(n, INF);
        vector<bool> visited(n, false);
        dist[src] = 0;

        for (int iter = 0; iter < n; iter++) {
            int u = -1;
            long long minDist = INF;
            for (int i = 0; i < n; i++) {
                if (!visited[i] && dist[i] < minDist) {
                    minDist = dist[i];
                    u = i;
                }
            }
            if (u == -1) break;
            visited[u] = true;

            for (int v = 0; v < n; v++) {
                if (visited[v]) continue;
                long long manhattan = (long long)abs(points[v].first - points[u].first) 
                                    + abs(points[v].second - points[u].second);
                if (dist[u] + manhattan < dist[v]) {
                    dist[v] = dist[u] + manhattan;
                }
            }

            for (auto& edge : specialAdj[u]) {
                int v = edge.first;
                int c = edge.second;
                if (dist[u] + c < dist[v]) {
                    dist[v] = dist[u] + c;
                }
            }
        }

        return (int)dist[dst];
    }
};
